(function(root){
'use strict';
const formats={post:{label:'Feed vertical',width:1080,height:1350},square:{label:'Feed quadrado',width:1080,height:1080},carousel:{label:'Carrossel',width:1080,height:1350},story:{label:'Story',width:1080,height:1920},reels:{label:'Reels',width:1080,height:1920,video:true},video:{label:'Vídeo horizontal',width:1920,height:1080,video:true}};
const photos={'amalfi.jpg':'Costa Amalfitana','florence.jpg':'Florença','rome.jpg':'Roma'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const spec=s=>formats[s.format]||formats.post;
const scenes=s=>String(s.scenes||[s.title,s.subtitle,s.cta||'Planeje sua viagem com a gente.'].filter(Boolean).join('\n')).split('\n').map(x=>x.trim()).filter(Boolean).slice(0,8);
const imageSource=s=>/^data:image\/(jpeg|png|webp);base64,[a-zA-Z0-9+/=]+$/.test(s.image||'')?s.image:'assets/'+(photos[s.photo]?s.photo:'amalfi.jpg');
const field=(key,label,value,type='text',max=120)=>`<label class="form-field"><span>${label}</span><input data-marketing-field="${key}" value="${esc(value)}" type="${type}" maxlength="${max}"></label>`;
function render(s,agency,campaigns){const f=spec(s),cards=scenes(s);return `<section class="marketing-heading"><div><span class="eyebrow">STUDIO · MARKETING</span><h1>Da ideia à próxima viagem.</h1><p>Crie peças com a identidade da sua agência e prepare seu conteúdo para publicar.</p></div><div class="marketing-actions"><button class="outline-button" data-action="marketing-new">Nova campanha</button><button class="primary-button" data-action="marketing-save">Salvar campanha</button></div></section><div class="marketing-layout"><aside class="marketing-controls"><h2>Formato e conteúdo</h2><div class="marketing-formats" role="group" aria-label="Formato">${Object.entries(formats).map(([id,v])=>`<button data-action="marketing-format" data-id="${id}" aria-pressed="${s.format===id}">${v.label}<small>${v.width} × ${v.height}</small></button>`).join('')}</div><label class="form-field"><span>Estilo</span><select data-marketing-field="template"><option value="dolce" ${s.template!=='clean'?'selected':''}>Editorial</option><option value="clean" ${s.template==='clean'?'selected':''}>Essencial</option></select></label><label class="form-field"><span>Fotografia</span><select data-marketing-field="photo">${Object.entries(photos).map(([id,label])=>`<option value="${id}" ${s.photo===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="marketing-upload">Usar minha imagem<input type="file" data-marketing-upload accept="image/png,image/jpeg,image/webp"></label>${s.image?'<button class="text-button" data-action="marketing-remove-image">Usar fotografia do modelo</button>':''}${field('title','Título',s.title,'text',80)}${field('subtitle','Chamada',s.subtitle)}${field('cta','Convite para contato',s.cta||'Fale com a nossa agência.')}<label class="form-field"><span>Cor da agência</span><input type="color" data-marketing-field="color" value="${/^#[0-9a-f]{6}$/i.test(s.color||'')?s.color:'#163e35'}"></label>${f.video||s.format==='carousel'?`<label class="form-field"><span>${f.video?'Roteiro: uma cena por linha':'Carrossel: um título por slide'} (até 8)</span><textarea data-marketing-field="scenes" rows="5" maxlength="1600">${esc(cards.join('\n'))}</textarea></label>`:''}${f.video?`<label class="form-field"><span>Duração total</span><select data-marketing-field="duration">${[6,10,15,20,30].map(n=>`<option value="${n}" ${Number(s.duration||10)===n?'selected':''}>${n} segundos</option>`).join('')}</select></label>`:''}<details class="marketing-brief"><summary>Briefing e planejamento</summary>${field('audience','Para quem?',s.audience||'')}${field('goal','Objetivo da campanha',s.goal||'')}${field('plannedAt','Data planejada',s.plannedAt||'','datetime-local')}<p class="form-hint">Data de organização interna. A publicação é feita por você na rede social.</p></details></aside><div class="marketing-output"><div class="marketing-preview-head"><span>${f.label} · ${f.width} × ${f.height}</span><span>${esc(agency)}</span></div><div class="marketing-preview"><canvas id="marketing-canvas" width="${f.width}" height="${f.height}" aria-label="Prévia da campanha"></canvas></div>${s.format==='carousel'?`<div class="marketing-slides" aria-label="Slide em edição">${cards.map((_,i)=>`<button data-action="marketing-slide" data-id="${i}" aria-pressed="${Number(s.slide||0)===i}">Slide ${i+1}</button>`).join('')}</div>`:''}<p id="marketing-status" role="status">${f.video?'Vídeo animado com foto e textos, sem áudio. A exportação usa os formatos disponíveis no seu navegador.':'Imagem pronta para exportar em PNG.'}</p><div class="marketing-actions"><button class="primary-button" data-action="marketing-export">${f.video?'Exportar vídeo':s.format==='carousel'?'Baixar este slide em PNG':'Baixar PNG'}</button>${f.video?'<button class="outline-button" data-action="marketing-cancel" hidden>Cancelar exportação</button>':''}<button class="outline-button" data-action="marketing-brief">Baixar roteiro e legenda</button></div><div class="marketing-caption"><h2>Legenda da publicação</h2><textarea data-marketing-field="caption" rows="5" maxlength="3000" aria-label="Legenda">${esc(s.caption)}</textarea><div class="marketing-actions"><button class="outline-button" data-action="backend-caption">Criar legenda com COS</button><button class="text-button" data-action="marketing-copy">Copiar legenda</button></div><p class="form-hint">Revise valores, condições e direitos das imagens antes de publicar. O COS usa o briefing para criar o texto quando a IA está conectada.</p></div></div></div><section class="marketing-library"><h2>Campanhas da agência</h2>${campaigns.length?`<div class="marketing-campaigns">${campaigns.map(c=>`<article><small>${esc(spec(c).label)}${c.plannedAt?' · '+esc(c.plannedAt.replace('T',' ')):''}</small><h3>${esc(c.title)}</h3><div class="marketing-actions"><button class="text-button" data-action="load-campaign" data-id="${esc(c.id)}">Editar</button><button class="text-button" data-action="marketing-duplicate" data-id="${esc(c.id)}">Duplicar</button></div></article>`).join('')}</div>`:'<p>Salve sua primeira campanha para retomar depois.</p>'}</section>`;}
function loadImage(src){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('Não foi possível abrir a imagem. Escolha outra fotografia.'));image.src=src;});}
function wrap(ctx,text,maxWidth,maxLines=4){const lines=[];let line='';for(const word of String(text).split(/\s+/)){const next=line?line+' '+word:word;if(ctx.measureText(next).width>maxWidth&&line){lines.push(line);line=word;}else line=next;}if(line)lines.push(line);if(lines.length>maxLines){lines.length=maxLines;lines[maxLines-1]=lines[maxLines-1].replace(/\s*\S*$/,'')+'…';}return lines;}
function draw(canvas,s,agency,image,progress=0,video=false){
 const f=spec(s),w=f.width,h=f.height;canvas.width=w;canvas.height=h;const c=canvas.getContext('2d');if(!c)throw Error('Seu navegador não disponibilizou a exportação de imagem.');
 const color=/^#[0-9a-f]{6}$/i.test(s.color||'')?s.color:'#163e35';c.fillStyle=color;c.fillRect(0,0,w,h);
 if(image){const scale=Math.max(w/image.width,h/image.height)*(video?1+.06*progress:1),iw=image.width*scale,ih=image.height*scale;c.drawImage(image,(w-iw)/2,(h-ih)/2,iw,ih);}
 const gradient=c.createLinearGradient(0,0,0,h);gradient.addColorStop(0,'rgba(0,0,0,.36)');gradient.addColorStop(.25,'rgba(0,0,0,.05)');gradient.addColorStop(1,s.template==='clean'?color:'rgba(0,0,0,.85)');c.fillStyle=gradient;c.fillRect(0,0,w,h);
 const pad=w*.075,unit=Math.min(w,h);c.fillStyle='white';c.font=`500 ${Math.round(unit*.025)}px sans-serif`;c.fillText(String(agency).toUpperCase(),pad,h*.07,w-pad*2);
 const cards=scenes(s),index=video?Math.min(cards.length-1,Math.floor(progress*cards.length)):Math.min(cards.length-1,Number(s.slide)||0),title=s.format==='carousel'||video?cards[index]||s.title:s.title;
 c.font=`${s.template==='clean'?'600':'500'} ${Math.round(unit*.078)}px ${s.template==='clean'?'sans-serif':'Georgia'}`;const lines=wrap(c,title,w-pad*2),lineHeight=unit*.092;let y=h*.71-lines.length*lineHeight/2;for(const line of lines){c.fillText(line,pad,y,w-pad*2);y+=lineHeight;}
 c.font=`400 ${Math.round(unit*.03)}px sans-serif`;for(const line of wrap(c,s.subtitle,w-pad*2,2)){c.fillText(line,pad,y+unit*.025,w-pad*2);y+=unit*.042;}
 c.fillStyle='#ffffff';c.font=`600 ${Math.round(unit*.025)}px sans-serif`;c.fillText(s.cta||'Fale com a nossa agência.',pad,h*.9,w-pad*2);
 if(s.format==='carousel'){c.font=`500 ${Math.round(unit*.023)}px sans-serif`;c.fillText(`${index+1} / ${cards.length}`,w-pad*2,h*.96);}
 if(video){c.fillStyle='rgba(255,255,255,.3)';c.fillRect(pad,h*.95,w-pad*2,4);c.fillStyle='white';c.fillRect(pad,h*.95,(w-pad*2)*progress,4);}
}
let previewToken=0;
async function preview(s,agency){const token=++previewToken,canvas=document.getElementById('marketing-canvas');if(!canvas)return;const photo=await loadImage(imageSource(s));if(token===previewToken&&canvas.isConnected)draw(canvas,s,agency,photo);}
const filename=s=>'campanha-'+String(s.title||'viagem').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').slice(0,55).toLowerCase();
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function exportImage(s,agency){const canvas=document.createElement('canvas');draw(canvas,s,agency,await loadImage(imageSource(s)));const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Não foi possível exportar esta imagem.');download(blob,filename(s)+(s.format==='carousel'?'-slide-'+(Number(s.slide||0)+1):'')+'.png');}
let cancelExport=null;
async function exportVideo(s,agency,onProgress){
 if(cancelExport)throw Error('Já existe um vídeo em exportação. Aguarde ou cancele.');
 if(!root.MediaRecorder||!HTMLCanvasElement.prototype.captureStream)throw Error('Este navegador não exporta vídeo. Abra o Studio no Chrome ou Edge atualizado.');
 const mime=['video/mp4;codecs=avc1.42E01E','video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw Error('Nenhum formato de vídeo disponível neste navegador.');
 const photo=await loadImage(imageSource(s)),canvas=document.createElement('canvas'),duration=Math.min(30,Math.max(6,Number(s.duration)||10))*1000;
 draw(canvas,s,agency,photo,0,true);const stream=canvas.captureStream(30);let timer,recorder,cancelled=false;
 try{recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:6000000});const chunks=[];await new Promise((resolve,reject)=>{recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onerror=()=>reject(Error('O navegador interrompeu a exportação.'));recorder.onstop=resolve;cancelExport=()=>{cancelled=true;if(recorder.state!=='inactive')recorder.stop();};const start=performance.now();recorder.start(250);timer=setInterval(()=>{if(document.hidden){cancelExport();return;}const progress=Math.min(1,(performance.now()-start)/duration);draw(canvas,s,agency,photo,progress,true);onProgress(Math.round(progress*100));if(progress===1&&recorder.state!=='inactive')recorder.stop();},1000/30);});if(cancelled)throw Error('Exportação cancelada. Mantenha esta aba aberta para exportar.');if(!chunks.length)throw Error('O navegador não gerou o arquivo de vídeo.');download(new Blob(chunks,{type:mime}),filename(s)+(mime.startsWith('video/mp4')?'.mp4':'.webm'));return mime.startsWith('video/mp4')?'MP4':'WebM';}
 finally{clearInterval(timer);cancelExport=null;if(recorder&&recorder.state!=='inactive')recorder.stop();stream.getTracks().forEach(t=>t.stop());}
}
async function upload(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12000000)throw Error('Escolha uma imagem JPG, PNG ou WebP de até 12 MB.');const url=URL.createObjectURL(file);try{const img=await loadImage(url),canvas=document.createElement('canvas'),scale=Math.min(1,1600/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);let data;for(const quality of [.8,.65,.5,.35]){data=canvas.toDataURL('image/jpeg',quality);if(data.length<450000)return data;}throw Error('Escolha uma imagem mais simples ou menor.');}finally{URL.revokeObjectURL(url);}}
function brief(s,agency){return `${agency}\n${s.title}\n${spec(s).label} · ${spec(s).width} × ${spec(s).height}\nPúblico: ${s.audience||'A definir'}\nObjetivo: ${s.goal||'A definir'}\nPlanejado: ${s.plannedAt||'Sem data'}\n\nROTEIRO\n${scenes(s).map((x,i)=>`${i+1}. ${x}`).join('\n')}\n\nLEGENDA\n${s.caption||''}\n\nCHAMADA\n${s.cta||''}\n\nRascunho para revisão. Nenhuma publicação automática.\n`;}
root.TravelMarketing={formats,spec,scenes,imageSource,render,preview,draw,exportImage,exportVideo,upload,brief,download,cancel:()=>cancelExport?.()};
})(typeof window!=='undefined'?window:globalThis);
